        format: ARCHIVE_FORMAT_VERSION_V2,
        codec: ARCHIVE_CODEC_ID_V2,
        objectKey,
        sourceRowCount,
        sourceSnapshot: snapshot,
        sourceWalLsn: lsn,
        minTime,
        maxTime,
        sha256: archive.sha256,
        bytes: archive.bytes.length,
      };
